const config = $('Campaign Config').first().json;

let research = 'Dutch homeowners with solar save €500-€900/year on energy bills. Electricity price ~€0.32/kWh. Saldering net metering policy phases out in 2027 — homeowners who install now lock in maximum returns. BTW (VAT) on solar panels reduced to 0% since 2023. Growing adoption: over 1 in 4 Dutch homes now has solar. Key pain: high energy bills, dependency on grid, rising prices.';
try {
  if ($input.first().json.choices && $input.first().json.choices[0]) {
    research = $input.first().json.choices[0].message.content;
  }
} catch(e) {}

const prompt = `You are an expert solar advertising copywriter for the Netherlands market. Write in English.

MARKET RESEARCH (use these facts — never invent figures):
${research}

Write 5 Meta ad variants for ${config.client_name}, a residential solar installation company.
Target: ${config.target_audience} in ${config.location}
Offer: ${config.current_offer}

Each ad has 4 parts: hook, body, incentive, cta.

ANGLE RULES — follow exactly per ad:

Ad 1 — Cost Savings (angle: Pain & Relief)
- Hook formula: Name the specific financial pain with a research-verified euro figure. Max 10 words. Never start with We/Our/Solarify.
- Body: 2-3 short paragraphs. Lead with outcome not process. Name the pain, explain why, introduce solar as the natural solution. One research fact.
- Incentive: Reference BTW 0% exemption or savings figure from research.
- CTA: Max 5 words. Verb-first. Low-commitment (calculate/check/find out).

Ad 2 — Energy Independence (angle: Smart Upgrade)
- Hook formula: Financial logic framing — savings vs cost, or future self outcome. Max 10 words.
- Body: State the financial logic simply. Annual savings, payback period. One proof point from research.
- Incentive: Savings projection or BTW exemption.
- CTA: Max 5 words. Verb-first.

Ad 3 — Sustainability (angle: Insider Knowledge)
- Hook formula: Something most homeowners don\'t know — surprising but verifiable. Max 10 words.
- Body: Deliver the insight with a real fact. Why it matters to them personally. Forward-looking tone.
- Incentive: Free consultation as low-barrier entry.
- CTA: Max 5 words. Verb-first.

Ad 4 — Government Subsidies (angle: Subsidy Revelation — strongest angle)
- Hook formula: The government/overheid is covering part of the cost. Max 10 words. Frame as helpful information not a sales pitch.
- Body: Explain BTW 0% exemption and saldering policy simply. Who qualifies. What they receive. Why most people haven\'t acted yet.
- Incentive: Reference saldering 2027 deadline as real urgency — act now to maximise returns.
- CTA: Max 5 words. Verb-first.

Ad 5 — Home Value (angle: Smart Upgrade)
- Hook formula: Specific number — home value increase or savings figure from research. Max 10 words.
- Body: Financial logic — solar as asset, not cost. Payback period. Resale value impact.
- Incentive: BTW exemption makes upfront cost lower than expected.
- CTA: Max 5 words. Verb-first.

Return ONLY a valid JSON array with exactly 5 objects. No markdown, no explanation:
[
  {
    "angle_name": "Cost Savings",
    "hook": "write the hook here",
    "body": "write the body here",
    "incentive": "write the incentive here",
    "cta": "write the cta here"
  }
]

Return ONLY the JSON array.`;

return [{
  json: {
    ...config,
    research,
    copy_request: {
      model: 'sonar-pro',
      max_tokens: 2048,
      messages: [{role: 'user', content: prompt}]
    }
  }
}];

const response = $input.first().json;
const config = $('Campaign Config').first().json;

let responseText;
try {
  responseText = response.choices[0].message.content;
} catch(e) {
  throw new Error('Perplexity response malformed: ' + JSON.stringify(response).substring(0, 200));
}

const jsonMatch = responseText.match(/\[[\s\S]*\]/);
if (!jsonMatch) throw new Error('No JSON array found: ' + responseText.substring(0, 300));

let angles;
try { angles = JSON.parse(jsonMatch[0]); } catch(e) { throw new Error('JSON parse failed: ' + e.message); }
if (!Array.isArray(angles) || angles.length === 0) throw new Error('Empty angles array');

return angles.map((angle, index) => ({
  json: {
    client_name: config.client_name,
    batch_id: config.batch_id,
    drive_folder_id: config.drive_folder_id,
    openai_api_key: config.openai_api_key,
    spreadsheet_id: config.spreadsheet_id,
    angle_index: index + 1,
    angle_name: angle.angle_name || ('Angle ' + (index + 1)),
    hook: angle.hook || '',
    body: angle.body || '',
    incentive: angle.incentive || '',
    cta: angle.cta || ''
  }
}));

const item = $input.first().json;
const prompt = 'Photorealistic modern Dutch suburban home interior, bright open kitchen with white cabinetry and stone countertops, mid-40s homeowner standing at kitchen counter looking at smartphone with relieved and satisfied expression, not looking at camera, candid authentic feel, warm natural window light with soft ambient interior fill, eye-level perspective, shallow depth of field sharp subject softly blurred background, calm in-control relieved atmosphere, high-end advertising photography, clean minimal composition, smooth out-of-focus background at top third for dark text overlay';
return [{ json: { ...item, angle_label: 'cost_savings', dalle_request: { model: 'dall-e-3', prompt, n: 1, size: '1024x1792', quality: 'hd', style: 'natural', response_format: 'b64_json' } } }];

const response = $input.first().json;
const angleData = $('Build Image Prompt 1').item.json;
const base64Data = response.data && response.data[0] && response.data[0].b64_json;
const fileName = 'solarify_' + (angleData.angle_label || 'angle1') + '_' + (angleData.batch_id || 'batch') + '.png';
if (!base64Data) return [{ json: { ...angleData, fileName, image_generated: false, error: JSON.stringify(response).substring(0, 200) } }];
return [{ json: { ...angleData, fileName, image_generated: true }, binary: { data: { data: base64Data, mimeType: 'image/png', fileName, fileExtension: 'png' } } }];

const driveOutput = $input.first().json;
const angleData = $('Build Image Prompt 1').item.json;

let imageUrl = 'Drive upload pending credential';
try {
  if (driveOutput.webViewLink) {
    imageUrl = driveOutput.webViewLink;
  } else if (driveOutput.id) {
    imageUrl = 'https://drive.google.com/file/d/' + driveOutput.id + '/view';
  }
} catch(e) {}

return [{
  json: {
    'Batch ID': angleData.batch_id || '',
    'Client': angleData.client_name || 'Solarify',
    'Angle': angleData.angle_name || '',
    'Hook': angleData.hook || '',
    'Body Copy': angleData.body || '',
    'Incentive': angleData.incentive || '',
    'CTA': angleData.cta || '',
    'Image Prompt': angleData.dalle_request ? angleData.dalle_request.prompt : '',
    'Image URL': imageUrl,
    'Status': 'Pending Review'
  }
}];

